<section x-data="assessmentPage" @cycle-changed.window="load()">
<div class="breadcrumb">{{ $config['roleLabel'] }} / {{ $config['scope'] }} / Penilaian</div><div class="page-heading"><div><h1 x-text="ui.page==='heads' ? 'Nilai Kepala Unit' : ui.page==='approvals' ? 'Persetujuan penilaian' : ui.page==='detail' ? 'Lembar penilaian' : 'Isi nilai karyawan'"></h1><p x-text="ui.page==='approvals' ? 'Angka nilai anggota hanya baca. ACC Anda langsung menjadi Final.' : ui.page==='heads' ? 'Isi KPI Kepala Unit dalam naungan divisi Anda. Penetapan langsung menjadi Final.' : 'Nilai bilangan bulat 10–100. Tekan Enter untuk pindah ke KPI berikutnya.'"></p></div><div class="button-row" x-show="current"><button class="btn" type="button" @click="reloadCurrent()" :disabled="busy || detailBusy"><x-icon name="refresh"/>Muat ulang</button><button class="btn" type="button" x-show="ui.role==='kepala_unit' && canEdit" :disabled="!comparison?.available" @click="copyPrevious()">Salin nilai bulan lalu</button></div></div>
<div class="tabs" role="tablist" aria-label="Status pengajuan" x-show="ui.page==='approvals'"><template x-for="t in [['submitted','Menunggu'],['returned','Dikembalikan'],['final','Final'],['all','Semua']]" :key="t[0]"><button type="button" role="tab" class="tab" :class="{active:tab===t[0]}" :aria-selected="tab===t[0]" @click="tab=t[0];load()" x-text="t[1]"></button></template><button type="button" class="btn ml-auto" @click="bulkApprove()" :disabled="!selectedIds.length" x-text="'ACC '+selectedIds.length+' terpilih'"></button></div>
<x-page-state :empty="'!ui.cycleId'" title="Belum ada periode" message="Hubungi Super HC untuk menyiapkan periode penilaian."/>
<div class="split" :class="{'!grid-cols-1':ui.page==='detail'}" x-cloak x-show="!loading && !loadError && ui.cycleId">
<aside class="panel rail" x-show="ui.page!=='detail'"><h2 class="panel-title" x-text="ui.page==='heads' ? 'Kepala Unit divisi' : ui.page==='approvals' ? 'Pengajuan anggota' : 'Karyawan unit'"></h2><div class="field" x-show="ui.role==='kepala_divisi'"><label for="assessment-unit">Unit</label><select id="assessment-unit" x-model="unitFilter" @change="load()"><option value="">Semua unit divisi</option><template x-for="unit in units" :key="unit.id"><option :value="unit.id" x-text="unit.name"></option></template></select></div><div class="field"><label for="assessment-search">Cari karyawan</label><input id="assessment-search" type="search" x-model="search" @input.debounce.300ms="load()" placeholder="Cari nama / NIP…"></div><div class="tabs !mb-0" x-show="ui.page!=='approvals'"><button class="tab" type="button" :class="{active:personTab==='all'}" @click="personTab='all'">Semua</button><button class="tab" type="button" :class="{active:personTab==='needed'}" @click="personTab='needed'">Perlu diisi</button></div><div class="rail-list"><template x-for="row in visibleRows" :key="row.id"><div class="flex gap-1 items-start"><input x-show="ui.page==='approvals' && row.status==='submitted'" type="checkbox" :value="row.id" x-model="selectedIds" :aria-label="'Pilih '+row.employee_name_snapshot" class="mt-4"><button class="rail-row" type="button" :class="{selected:current && (current.id===(row.assessment_id||row.id))}" @click="choose(row)" :disabled="detailBusy"><strong x-text="row.employee_name_snapshot || row.full_name"></strong><x-badge/><span class="small muted" x-text="row.unit_name_snapshot || row.unit_name"></span></button></div></template><p class="muted small py-3" x-show="!visibleRows.length">Tidak ada karyawan sesuai filter.</p></div><x-pagination/></aside>
<div class="min-w-0"><div class="panel loading" x-show="detailBusy" role="status"><p class="muted">Memuat lembar penilaian…</p><div class="skeleton"></div><div class="skeleton"></div></div><div class="notice notice-error mb-4" x-show="detailError" x-text="detailError" role="alert"></div><div class="panel empty" x-show="!current && !detailBusy"><x-icon name="clipboard"/><h2>Pilih karyawan</h2><p>Pilih nama pada daftar untuk mulai mengisi atau meninjau penilaian.</p></div>
<template x-if="current && !detailBusy"><div><div class="panel panel-pad"><div class="person-heading"><div><h2 x-text="current.employee_name_snapshot"></h2><p x-text="current.position_name_snapshot+' · '+current.nip_snapshot+' · Template: '+current.template_name_snapshot+' / v'+current.template_version_snapshot"></p></div><x-badge value="current.status"/></div><div class="notice notice-warning mb-4" x-show="current.status==='returned'"><strong>Catatan pengembalian</strong><p x-text="returnReason || 'Baca riwayat pengembalian sebelum melakukan revisi.'"></p></div><div class="notice mb-4" x-show="current.status==='final'"><strong class="flex items-center gap-2"><x-icon name="lock"/>Final, nilai terkunci</strong>Keputusan akhir ditetapkan Kepala Divisi. Penilaian ini hanya dapat dibaca.</div><div class="notice notice-warning mb-4" x-show="!canEdit && ['draft','returned'].includes(current.status)">Pengisian belum dibuka, tenggat telah berakhir, atau akun Anda hanya memiliki akses baca.</div>
<div class="notice mb-4" x-show="review && current.total_score_raw!==null"><strong class="text-[26px] num" x-text="$number(current.total_score_raw)"></strong><span x-text="current.category_label_snapshot || category"></span><p class="small mt-1" x-text="comparison?.available ? 'Bulan sebelumnya: '+$number(comparison.total)+' · template sama' : comparison?.message"></p></div>
<div class="table-wrap"><table class="table score-table"><thead><tr><th>Pilar</th><th>KPI</th><th>Target</th><th class="numeric">Bobot</th><th class="numeric">Nilai</th><th class="numeric">Hasil</th><th class="numeric" x-show="review">Δ bulan lalu</th></tr></thead><tbody><template x-for="(item,index) in current.items" :key="item.id"><tr><td x-text="item.pillar_snapshot"></td><td><span x-text="item.kpi_name_snapshot"></span><details x-show="item.numerator_snapshot || item.denominator_snapshot || item.formula_snapshot" class="small mt-1"><summary class="brand cursor-pointer">Rincian pengukuran</summary><p x-text="'Numerator: '+(item.numerator_snapshot || 'Tidak ditentukan')"></p><p x-text="'Denominator: '+(item.denominator_snapshot || 'Tidak ditentukan')"></p><p x-text="'Formula: '+(item.formula_snapshot || 'Tidak ditentukan')"></p></details></td><td data-label="Target" x-text="item.target_snapshot || 'Tidak ditentukan'"></td><td class="numeric" data-label="Bobot" x-text="$number(item.weight_percent_snapshot,2)+'%'"></td><td class="numeric" data-label="Nilai"><template x-if="canEdit"><div><label class="sr-only" :for="'score-'+item.id" x-text="'Nilai '+item.kpi_name_snapshot"></label><input class="score" data-score :id="'score-'+item.id" type="text" inputmode="numeric" pattern="(?:[1-9][0-9]|100)" maxlength="3" x-model="item.score" @input="dirty=true" @keydown.enter.prevent="nextInput($event)" :aria-invalid="!!errors['scores.'+index+'.score']"><p class="field-error" x-text="errors['scores.'+index+'.score']?.[0] || ''"></p></div></template><span x-show="!canEdit" x-text="item.score===null ? 'Belum diisi' : item.score"></span></td><td class="numeric" data-label="Hasil" x-text="result(item)"></td><td class="numeric" x-show="review" x-text="delta(item)"></td></tr></template></tbody></table><div class="table-foot" x-text="'Total bobot '+$number(weightTotal,2)+'% · '+filled+' dari '+current.items.length+' KPI terisi · Hasil = nilai × bobot / 100'"></div></div>
<div class="finding-grid"><div><label for="positive-finding">Temuan positif (opsional)</label><textarea id="positive-finding" x-model="current.positive_finding" :readonly="!canEdit" @input="dirty=true" maxlength="10000" placeholder="Tambahkan catatan bila ada…"></textarea></div><div><label for="negative-finding">Temuan negatif (opsional)</label><textarea id="negative-finding" x-model="current.negative_finding" :readonly="!canEdit" @input="dirty=true" maxlength="10000" placeholder="Tambahkan catatan bila ada…"></textarea></div></div><p class="notice notice-error mt-4" x-show="formError" x-text="formError" role="alert"></p>
</div><div class="editor-footer"><div><p class="small brand" x-text="complete?'Total nilai':'Subtotal sementara'"></p><strong class="score-total num" x-text="$number(total)"></strong><span class="brand ml-4" x-text="current.category_label_snapshot || category"></span><p class="small muted" x-show="dirty">Perubahan belum disimpan.</p></div><div class="button-row"><button class="btn" type="button" x-show="canEdit" @click="save()" :disabled="busy" x-text="busy ? 'Menyimpan…' : 'Simpan draft'"></button><button class="btn btn-primary" type="button" x-show="canEdit" @click="submit()" :disabled="busy || !complete || weightTotal!==100" x-text="current.assessment_kind==='unit_head' ? 'Tetapkan nilai Final' : 'Ajukan penilaian'"></button><button class="btn" type="button" x-show="ui.role==='kepala_unit' && current.status==='submitted'" @click="withdraw()">Tarik kembali</button><button class="btn" type="button" x-show="review && current.status==='submitted'" @click="decide('return')">Kembalikan</button><button class="btn btn-primary" type="button" x-show="review && current.status==='submitted'" @click="decide('approve')">ACC dan tetapkan Final</button></div></div>
<div class="panel panel-pad mt-4">
    <h2 class="panel-title mb-5">Riwayat penilaian</h2>
    <div class="audit-list">
        <template x-for="event in timeline" :key="event.id">
            <div class="audit-event">
                <strong x-text="ui.actionLabel(event.action)"></strong>
                <p class="small muted" x-text="ui.dateTime(event.recorded_at)+' · '+(event.actor_name || ui.roleName(event.actor_role_key))"></p>
                <p x-show="event.reason" x-text="event.reason"></p>
            </div>
        </template>
    </div>
    <button type="button" class="btn mt-4" x-show="timelinePagination?.next_page_url" :disabled="timelineBusy" @click="moreTimeline()" x-text="timelineBusy ? 'Memuat riwayat…' : 'Lihat riwayat lebih lama'"></button>
</div></div></template></div></div>
</section>
